INSERT INTO training_knowledge.sources (id,data) VALUES ('S38','{"id": "S38", "title": "NHS: opvarmning før træning", "url": "https://www.nhs.uk/live-well/exercise/how-to-warm-up-before-exercising/", "type": "public_health_or_hospital", "summary": "Generelle eksempler på gradvis opvarmning og kontrollerede dynamiske bevægelser. Egne korte instruktioner; individuel varighed, egnethed og bevægeudslag kræver gennemgang.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
